create type public.finance_document_status as enum ('draft', 'active', 'cancelled');
create type public.finance_proposal_status as enum ('draft', 'sent', 'accepted', 'rejected', 'cancelled');
create type public.finance_invoice_status as enum ('pending', 'confirmed', 'cancelled');
create type public.finance_entitlement_status as enum ('pending', 'eligible', 'suspended', 'expired', 'cancelled');

create table public.finance_offers (id uuid primary key default gen_random_uuid(), code text not null unique check (code ~ '^[a-z0-9][a-z0-9-]{1,62}$'), name text not null check (char_length(trim(name)) between 2 and 180), status public.finance_document_status not null default 'draft', created_by uuid not null references public.identities(id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.finance_price_versions (id uuid primary key default gen_random_uuid(), offer_id uuid not null references public.finance_offers(id) on delete restrict, amount numeric(12,2) not null check (amount >= 0), currency_code text not null default 'BRL' check (currency_code ~ '^[A-Z]{3}$'), valid_from date not null default current_date, valid_until date, status public.finance_document_status not null default 'draft', created_by uuid not null references public.identities(id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (valid_until is null or valid_until >= valid_from));
create table public.finance_proposals (id uuid primary key default gen_random_uuid(), crm_opportunity_id uuid not null references public.crm_opportunities(id) on delete restrict, price_version_id uuid not null references public.finance_price_versions(id) on delete restrict, amount numeric(12,2) not null check (amount >= 0), currency_code text not null default 'BRL' check (currency_code ~ '^[A-Z]{3}$'), status public.finance_proposal_status not null default 'draft', expires_on date, created_by uuid not null references public.identities(id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.finance_contracts (id uuid primary key default gen_random_uuid(), proposal_id uuid not null unique references public.finance_proposals(id) on delete restrict, status public.finance_document_status not null default 'draft', starts_on date, ends_on date, created_by uuid not null references public.identities(id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (ends_on is null or starts_on is null or ends_on >= starts_on));
create table public.finance_invoices (id uuid primary key default gen_random_uuid(), contract_id uuid not null references public.finance_contracts(id) on delete restrict, amount numeric(12,2) not null check (amount >= 0), currency_code text not null default 'BRL' check (currency_code ~ '^[A-Z]{3}$'), due_on date, status public.finance_invoice_status not null default 'pending', external_reference text unique check (external_reference is null or char_length(trim(external_reference)) between 2 and 160), created_by uuid not null references public.identities(id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.finance_payment_confirmations (id uuid primary key default gen_random_uuid(), invoice_id uuid not null unique references public.finance_invoices(id) on delete restrict, amount numeric(12,2) not null check (amount >= 0), confirmed_at timestamptz not null default now(), method_label text check (method_label is null or char_length(trim(method_label)) <= 80), external_reference text check (external_reference is null or char_length(trim(external_reference)) between 2 and 160), recorded_by uuid not null references public.identities(id) on delete restrict, created_at timestamptz not null default now());
create table public.finance_entitlements (id uuid primary key default gen_random_uuid(), contract_id uuid not null unique references public.finance_contracts(id) on delete restrict, status public.finance_entitlement_status not null default 'pending', eligible_from timestamptz, eligible_until timestamptz, created_by uuid not null references public.identities(id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (eligible_until is null or eligible_from is null or eligible_until >= eligible_from));
create table public.finance_audit_events (id uuid primary key default gen_random_uuid(), actor_identity_id uuid not null references public.identities(id) on delete restrict, action text not null check (char_length(action) between 2 and 100), resource_type text not null check (char_length(resource_type) between 2 and 100), resource_id uuid not null, metadata jsonb not null default '{}'::jsonb check (jsonb_typeof(metadata) = 'object' and octet_length(metadata::text) <= 8192), created_at timestamptz not null default now());
create index finance_proposals_opportunity_idx on public.finance_proposals (crm_opportunity_id, created_at desc); create index finance_invoices_contract_idx on public.finance_invoices (contract_id, status, due_on);

alter table public.finance_offers enable row level security; alter table public.finance_price_versions enable row level security; alter table public.finance_proposals enable row level security; alter table public.finance_contracts enable row level security; alter table public.finance_invoices enable row level security; alter table public.finance_payment_confirmations enable row level security; alter table public.finance_entitlements enable row level security; alter table public.finance_audit_events enable row level security;
revoke all on public.finance_offers, public.finance_price_versions, public.finance_proposals, public.finance_contracts, public.finance_invoices, public.finance_payment_confirmations, public.finance_entitlements, public.finance_audit_events from anon, authenticated;
create policy "finance offers deny direct access" on public.finance_offers for all to anon, authenticated using (false) with check (false); create policy "finance prices deny direct access" on public.finance_price_versions for all to anon, authenticated using (false) with check (false); create policy "finance proposals deny direct access" on public.finance_proposals for all to anon, authenticated using (false) with check (false); create policy "finance contracts deny direct access" on public.finance_contracts for all to anon, authenticated using (false) with check (false); create policy "finance invoices deny direct access" on public.finance_invoices for all to anon, authenticated using (false) with check (false); create policy "finance payments deny direct access" on public.finance_payment_confirmations for all to anon, authenticated using (false) with check (false); create policy "finance entitlements deny direct access" on public.finance_entitlements for all to anon, authenticated using (false) with check (false); create policy "finance audit deny direct access" on public.finance_audit_events for all to anon, authenticated using (false) with check (false);

create or replace function private.has_internal_capability(target_identity_id uuid, target_capability text) returns boolean language sql stable security definer set search_path = '' as $$ select case target_capability when 'manage_roles' then private.has_internal_role(target_identity_id, 'admin') when 'crm_read_all' then private.has_internal_role(target_identity_id, 'admin') when 'crm_read_assigned' then private.has_internal_role(target_identity_id, 'admin') or private.has_internal_role(target_identity_id, 'commercial') when 'crm_write_assigned' then private.has_internal_role(target_identity_id, 'admin') or private.has_internal_role(target_identity_id, 'commercial') when 'crm_handoff_create' then private.has_internal_role(target_identity_id, 'admin') or private.has_internal_role(target_identity_id, 'commercial') when 'handoff_read_assigned' then private.has_internal_role(target_identity_id, 'admin') or private.has_internal_role(target_identity_id, 'concierge') when 'handoff_accept_assigned' then private.has_internal_role(target_identity_id, 'admin') or private.has_internal_role(target_identity_id, 'concierge') when 'manage_enrollments' then private.has_internal_role(target_identity_id, 'admin') or private.has_internal_role(target_identity_id, 'concierge') when 'finance_catalog_write' then private.has_internal_role(target_identity_id, 'admin') or private.has_internal_role(target_identity_id, 'finance') when 'finance_read_all' then private.has_internal_role(target_identity_id, 'admin') or private.has_internal_role(target_identity_id, 'finance') when 'finance_proposal_create' then private.has_internal_role(target_identity_id, 'admin') or private.has_internal_role(target_identity_id, 'finance') or private.has_internal_role(target_identity_id, 'commercial') when 'finance_contract_write' then private.has_internal_role(target_identity_id, 'admin') or private.has_internal_role(target_identity_id, 'finance') else false end; $$;

create or replace function public.create_finance_offer(target_code text, target_name text, target_amount numeric, target_currency text default 'BRL') returns uuid language plpgsql security definer set search_path = '' as $$ declare actor_id uuid := auth.uid(); offer_id uuid; begin if actor_id is null or not private.has_internal_capability(actor_id, 'finance_catalog_write') then raise exception 'finance catalog access required' using errcode = '42501'; end if; insert into public.finance_offers (code, name, status, created_by) values (lower(trim(target_code)), trim(target_name), 'active', actor_id) returning id into offer_id; insert into public.finance_price_versions (offer_id, amount, currency_code, status, created_by) values (offer_id, target_amount, upper(trim(target_currency)), 'active', actor_id); insert into public.finance_audit_events (actor_identity_id, action, resource_type, resource_id) values (actor_id, 'offer_created', 'finance_offer', offer_id); return offer_id; end; $$;
create or replace function public.create_finance_proposal(target_crm_opportunity_id uuid, target_price_version_id uuid, target_expires_on date default null) returns uuid language plpgsql security definer set search_path = '' as $$ declare actor_id uuid := auth.uid(); proposal_id uuid; price_record record; begin if actor_id is null or not private.has_internal_capability(actor_id, 'finance_proposal_create') then raise exception 'finance proposal access required' using errcode = '42501'; end if; if not exists (select 1 from public.crm_opportunities opportunity where opportunity.id = target_crm_opportunity_id and (private.has_internal_capability(actor_id, 'finance_read_all') or opportunity.owner_identity_id = actor_id)) then raise exception 'opportunity access required' using errcode = '42501'; end if; select amount, currency_code into price_record from public.finance_price_versions where id = target_price_version_id and status = 'active'; if not found then raise exception 'active price version required' using errcode = 'P0002'; end if; insert into public.finance_proposals (crm_opportunity_id, price_version_id, amount, currency_code, expires_on, created_by) values (target_crm_opportunity_id, target_price_version_id, price_record.amount, price_record.currency_code, target_expires_on, actor_id) returning id into proposal_id; insert into public.finance_audit_events (actor_identity_id, action, resource_type, resource_id) values (actor_id, 'proposal_created', 'finance_proposal', proposal_id); return proposal_id; end; $$;
create or replace function public.confirm_finance_payment(target_proposal_id uuid, target_due_on date default null, target_method_label text default null, target_external_reference text default null) returns uuid language plpgsql security definer set search_path = '' as $$ declare actor_id uuid := auth.uid(); contract_id uuid; invoice_id uuid; entitlement_id uuid; proposal_record record; begin if actor_id is null or not private.has_internal_capability(actor_id, 'finance_contract_write') then raise exception 'finance access required' using errcode = '42501'; end if; select * into proposal_record from public.finance_proposals where id = target_proposal_id and status in ('draft', 'sent', 'accepted'); if not found then raise exception 'active proposal required' using errcode = 'P0002'; end if; update public.finance_proposals set status = 'accepted', updated_at = now() where id = target_proposal_id; insert into public.finance_contracts (proposal_id, status, starts_on, created_by) values (target_proposal_id, 'active', current_date, actor_id) on conflict (proposal_id) do update set status = 'active', updated_at = now() returning id into contract_id; insert into public.finance_invoices (contract_id, amount, currency_code, due_on, status, external_reference, created_by) values (contract_id, proposal_record.amount, proposal_record.currency_code, target_due_on, 'confirmed', target_external_reference, actor_id) returning id into invoice_id; insert into public.finance_payment_confirmations (invoice_id, amount, method_label, external_reference, recorded_by) values (invoice_id, proposal_record.amount, nullif(trim(target_method_label), ''), nullif(trim(target_external_reference), ''), actor_id); insert into public.finance_entitlements (contract_id, status, eligible_from, created_by) values (contract_id, 'eligible', now(), actor_id) on conflict (contract_id) do update set status = 'eligible', eligible_from = now(), updated_at = now() returning id into entitlement_id; insert into public.finance_audit_events (actor_identity_id, action, resource_type, resource_id, metadata) values (actor_id, 'payment_confirmed_manually', 'finance_payment_confirmation', invoice_id, jsonb_build_object('entitlement_id', entitlement_id)); return invoice_id; end; $$;
create or replace function public.get_my_finance_workspace() returns jsonb language sql stable security definer set search_path = '' as $$ with actor as (select auth.uid() as identity_id), offers as (select offer.id, offer.code, offer.name, price.id as price_version_id, price.amount, price.currency_code from public.finance_offers offer join public.finance_price_versions price on price.offer_id = offer.id cross join actor where offer.status = 'active' and price.status = 'active' and private.has_internal_capability(actor.identity_id, 'finance_proposal_create')), proposals as (select proposal.id, proposal.status, proposal.amount, proposal.currency_code, proposal.expires_on, opportunity.title as opportunity_title, account.name as account_name from public.finance_proposals proposal join public.crm_opportunities opportunity on opportunity.id = proposal.crm_opportunity_id join public.crm_accounts account on account.id = opportunity.account_id cross join actor where private.has_internal_capability(actor.identity_id, 'finance_read_all') or (private.has_internal_capability(actor.identity_id, 'finance_proposal_create') and opportunity.owner_identity_id = actor.identity_id)) select jsonb_build_object('offers', coalesce((select jsonb_agg(to_jsonb(offers) order by name) from offers), '[]'::jsonb), 'proposals', coalesce((select jsonb_agg(to_jsonb(proposals) order by expires_on nulls last, opportunity_title) from proposals), '[]'::jsonb)); $$;
revoke all on function public.create_finance_offer(text, text, numeric, text), public.create_finance_proposal(uuid, uuid, date), public.confirm_finance_payment(uuid, date, text, text), public.get_my_finance_workspace() from public; revoke execute on function public.create_finance_offer(text, text, numeric, text), public.create_finance_proposal(uuid, uuid, date), public.confirm_finance_payment(uuid, date, text, text), public.get_my_finance_workspace() from anon; grant execute on function public.create_finance_offer(text, text, numeric, text), public.create_finance_proposal(uuid, uuid, date), public.confirm_finance_payment(uuid, date, text, text), public.get_my_finance_workspace() to authenticated;
